import{_ as n,a0 as s,w as p,s as m,I as l,x as i,a1 as e,A as t,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"开源领域中姐妹情谊和盟友关系的力量 | LCTT x X-CMD","titleTemplate":false,"description":"开源领域中姐妹情谊和盟友关系的力量 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开源领域中姐妹情谊和盟友关系的力量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开源领域中姐妹情谊和盟友关系的力量 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230308.6 ⭐️⭐️ The power of sisterhood and allyship in open source","title":"开源领域中姐妹情谊和盟友关系的力量","tag":"202304","desc":""},"relativePath":"202304/20230308.6 ⭐️⭐️ The power of sisterhood and allyship in open source.md","filePath":"[post].md"}'),u={name:"202304/20230308.6 ⭐️⭐️ The power of sisterhood and allyship in open source.md"};function d(f,r,T,g,y,C){const o=s("Link");return p(),m("div",null,[r[36]||(r[36]=l("h1",{id:"开源领域中姐妹情谊和盟友关系的力量",tabindex:"-1"},[i("开源领域中姐妹情谊和盟友关系的力量 "),l("a",{class:"header-anchor",href:"#开源领域中姐妹情谊和盟友关系的力量","aria-label":"Permalink to “开源领域中姐妹情谊和盟友关系的力量”"},"​")],-1)),r[37]||(r[37]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/18/234855fuxewrdvwaey8jj1.jpg",alt:""})],-1)),r[38]||(r[38]=l("blockquote",null,[l("p",null,"“站在巨人的肩膀上”不仅是指开源，而且是指通过承认女性先驱和领导者在该领域的作用，在技术中建立姐妹情谊的基础。")],-1)),l("p",null,[r[1]||(r[1]=i("两年多前，我从艺术家转职成为一名 ",-1)),e(o,{href:"https://enterprisersproject.com/article/2022/9/software-developer-day-life?intcmp=7013a000002qLH8AAM"},{default:t(()=>[...r[0]||(r[0]=[i("软件开发人员",-1)])]),_:1}),r[2]||(r[2]=i("。我不是单凭一己之力做到的。 我得到了 PyLadies Berlin 的支持，PyLadies Berlin 是一个国际志愿者团体的柏林本地分会，旨在支持女性从事技术工作。",-1))]),r[39]||(r[39]=a('<p>我们习惯了“职业变化”这个词，就好像它是一个轨迹的中断。但根据我的经验，事实并非如此。一个人无法抹去自己过去的点点滴滴，而多样化背景带来的丰富性可以造就爆发点。个体的人生旅程虽然通常与计算机科学毫无相关，却担起了令科技对社会有所影响的职责，并为技术行业带来丰富性和创造力。</p><p>作为一名艺术家，我得到了自由，并打开了探索从建筑到科学等多个领域的大门。我大部分的艺术经历发生在巴西的黑客空间里，这里充斥着<ruby>自由及开源软件<rt>Free/Libre Open Source Software</rt></ruby>（FLOSS）的思想，即开放的自由共享文化。如今，由于一些不属于本文讨论范围的意识形态和实践原因，最常见的术语是“开源”。对我来说幸运的是，我的职业转变始于一次在 <ruby>开源项目办公室<rt>Open Source Program Office</rt></ruby>（OSPO）的实习，它让我的转变经历感觉——几乎可以说——像回家一样。</p><h3 id="放在巨人的肩膀上" tabindex="-1">放在巨人的肩膀上 <a class="header-anchor" href="#放在巨人的肩膀上" aria-label="Permalink to “放在巨人的肩膀上”">​</a></h3><p>我们都受益于开源。无论你是否编码，你所使用的软件都依赖于它。由于这是一种开放的文化，一切都建立在他人的工作之上，所以经常听到“站在巨人的肩膀上”这个表述，指的是我们的进步都建立在前人的工作和贡献之上。 这突出了从他人的经验和成就中学习的重要性。</p><p>这篇文章旨在揭示我站在谁的肩膀上。这不仅是为了表达我对他们的感激之情，也是为了回答我在接受 JSParty 的 Kevin Ball 和 Christopher Hiller 采访时被问到的一个问题：你能做些什么来改善周围环境的多样性？</p>',5)),l("p",null,[r[4]||(r[4]=i("“站在巨人的肩膀上”不仅是指开源，而且是指通过承认女性先驱和领导者在该领域的作用，在技术中建立姐妹情谊的基础。通过承认在我们之前的女性所做的贡献，我们可以从她们所面临的挑战中获得灵感和洞察力，并从她们挣脱束缚的经验中学习。通过这种方式，我们“站在巨人的肩膀上”，以她们的工作为基础，为女性和 ",-1)),e(o,{href:"https://www.if-me.org/"},{default:t(()=>[...r[3]||(r[3]=[i("被低估的",-1)])]),_:1}),r[5]||(r[5]=i(" 技术人员创造更具包容性和支持性的环境。",-1))]),r[40]||(r[40]=a('<p>通过相互支持，认识到从他人经验中学习的重要性，并形成一个支持网络，我们可以共同努力克服挑战，通过创造更公平的环境，为所有人建设更美好的未来。通过这样做，我们正在创造新的巨人，供其他人在未来立足。</p><h3 id="组织一个当地社区-meili-triantafyllidi-和-jessica-greene" tabindex="-1">组织一个当地社区: Meili Triantafyllidi 和 Jessica Greene <a class="header-anchor" href="#组织一个当地社区-meili-triantafyllidi-和-jessica-greene" aria-label="Permalink to “组织一个当地社区: Meili Triantafyllidi 和 Jessica Greene”">​</a></h3><p>我加入了 PyLadies Berlin，它由 Meili 于 2013 年创立。Jessica 是组织者之一，她是 Ecosia 的一名初级软件工程师。成为社区组织者意味着利用你个人的空闲时间和热情，尽力创建一个安全的、支持性的网络和学习空间。这些工作包括寻找举办地点、宣传活动、策划主题、寻找演讲者，最重要的是，倾听社区的需求。</p><p>作为多元文化城市的新人并试图在城市中找到自己的位置，我感到 PyLadies 与其说是一个学习 Python 的地方，不如说是一个让我感受到被欢迎和被理解的中心。</p><p>根据我们常常听到的叙述，科技领域是每个人都在前往的新希望之地，有无限的岗位需求、切换国家的自由和高薪的职业。其他行业没有提供这种服务，或者至少没有达到这种规模。专注于带来多样性空间的社区提供了使这对每个人都成为现实的可能性。</p><p>每个活动都以社区公告、包含议程的简单幻灯片以及类似活动的宣传开始。当时我听闻的两个活动引导我走上了我的职业道路：Rail Girls Summer of Code 计划和 FrauenLoop。因为感觉有必要回馈当初给予了我支持的社区，我成为了共同组织者之一。</p><h3 id="搭建人际关系网和学习专业知识-frauenloop" tabindex="-1">搭建人际关系网和学习专业知识: FrauenLoop <a class="header-anchor" href="#搭建人际关系网和学习专业知识-frauenloop" aria-label="Permalink to “搭建人际关系网和学习专业知识: FrauenLoop”">​</a></h3><p>FrauenLoop 由 Nakeema Stefflbauer 博士于 2016 年创立，致力于改变欧盟科技公司的面貌。该项目分为 3 个月的周期，由每周的晚间课程和周末研讨会组成，以培训在科技行业里没有人际关系网的女性。</p><p>学习课程是围绕女性的专业需求开发的，从以技术行业为重点的课程到女性举办的关于科技行业如何真正运作以及如何成功立足的研讨会。一些常见的话题包括薪资谈判和练习技术面试。最近，为了应对裁员，柏林技术工人联盟举办了一场研讨会，揭开如何对公司解雇流程提出质疑的神秘面纱。</p><p>研讨会聚焦于女性，尤其是移民群体，她们正处于家庭状况和职业转变的阶段，真正准备好去寻找工作了。</p><p>和 Nakeema 在一起本身就给我带来了灵感。该项目提供了理解编程和学习网页开发基础知识的起点。但最重要的是，你与项目中的其他人建立了联系，他们是 PyLadies 未来的共同组织者、演讲者、业余项目的导师和朋友。</p><p>FrauenLoop 还为其学生提供了回去担任导师的机会。对我来说，这是决定我前进道路的转折点。做了一年多的导师，增强了我对自己的信心，也巩固了我自己的学习。受到帮助他人学习这一责任的挑战，你不可避免要一直学习。</p><p>在那里我遇到了 Victoria Hodder，她是我申请 Rail Girls Summer of Code 时的搭档。</p><h3 id="多元化项目-从-rail-girls-summer-of-code-到-ecosia-summer-of-code" tabindex="-1">多元化项目：从 Rail Girls Summer of Code 到 Ecosia Summer of Code <a class="header-anchor" href="#多元化项目-从-rail-girls-summer-of-code-到-ecosia-summer-of-code" aria-label="Permalink to “多元化项目：从 Rail Girls Summer of Code 到 Ecosia Summer of Code”">​</a></h3><p>Rail Girls Summer of Code 是一项面向女性和非二元性别程序员的全球奖学金计划，入选的申请者将获得为期三个月的奖学金，以从事现有的开源项目。该计划活跃于 2013 年到 2020 年。</p><p>申请以一个团队为单位进行提交，即来自同一个城市的两个人。虽然这是一个远程项目，但有一个本地同行确保了问责制和相互支持。</p><p>除了同伴，项目还需要有一个办公的地方，一个适合工作三个月的环境。这个地方可以是你的家、联合办公空间、工作办公室，或者最好的情况下是培训公司。虽然培训公司除了提供工作空间外没有其他义务，但它让我们与当地公司联系起来，并为我们提供了一个空间，让我们能够与我们想进入的行业内的人建立知名度和关系网。</p><p>我在 PyLadies Berlin 的联合组织者 Jessica 通过该项目开启了她在科技领域的职业生涯。她提议 Ecosia（她当时也是现在所任职的公司）担任两个团队的指导工作，其中一个是我和 Victoria 的团队（我们专注于网络开发），另一个是 Taciana Cruz 和 Karina Cordeiro 的团队（他们专注于数据）。</p>',18)),l("p",null,[r[7]||(r[7]=i("在三个月的申请期内，大流行来势汹汹。在参与 ",-1)),e(o,{href:"https://www.if-me.org/"},{default:t(()=>[...r[6]||(r[6]=[i("if-me",-1)])]),_:1}),r[8]||(r[8]=i(" 项目后，我和维多利亚被 ",-1)),r[9]||(r[9]=l("em",null,"某种程度上",-1)),r[10]||(r[10]=i(" 选入了 the Rail Girls 项目。因为是 ",-1)),r[11]||(r[11]=l("em",null,"某种程度上",-1)),r[12]||(r[12]=i(" 被选中的，我们与 Rail Girls 的沟通在选拔后期变得非常混乱，最终他们在最后一刻取消了项目。",-1))]),r[41]||(r[41]=l("p",null,"我们当时都崩溃了。大流行的重压给我们带来了沉重打击，它不仅粉碎了我们获得一份有偿工作的机会，而且粉碎了长期以来养成的开始新职业的梦想。",-1)),l("p",null,[r[14]||(r[14]=i("当时还是初级软件开发人员的 Jessica懂我们的处境，因此她挺身而出，她没有感到无能为力，而是站出来表明自己的立场。除了为适应个人新角色所付出的努力，她还给自己安排了更多工作，并创建了 ",-1)),e(o,{href:"https://blog.ecosia.org/ecosia-summer-of-code-mentoring/"},{default:t(()=>[...r[13]||(r[13]=[i("Ecosia Summer of Code",-1)])]),_:1}),r[15]||(r[15]=i(" 这一项目。",-1))]),r[42]||(r[42]=l("p",null,"Ecosia 无法支付奖学金，但 Jessica 开发了一个导师计划。该计划利用公司的可用资源，提供高素质专业人士的指导，以填补我们的知识空白。由于 Victoria 和 Karina 因为需要有报酬的工作而放弃了项目，Taciana 和我设法继续进行个人项目。我们找到了可以一起努力并相互支持的共同主题。",-1)),r[43]||(r[43]=l("p",null,"大约一年后，其中一位导师 Jakiub Fialla 邀请我去她的公司聊聊开源。我与其他一些人依然保持着联系，时不时地，当他们举办 PyLadies Berlin 活动时，我会顺便过去见见他们。如此甜蜜。",-1)),r[44]||(r[44]=l("h3",{id:"赞助多样性-coyotiv-项目和它的创始人-armagan-amcalar",tabindex:"-1"},[i("赞助多样性: Coyotiv 项目和它的创始人 Armagan Amcalar "),l("a",{class:"header-anchor",href:"#赞助多样性-coyotiv-项目和它的创始人-armagan-amcalar","aria-label":"Permalink to “赞助多样性: Coyotiv 项目和它的创始人 Armagan Amcalar”"},"​")],-1)),r[45]||(r[45]=l("p",null,"当 Rail Girls 项目被取消时，我在 Instagram 上看到一篇关于训练营的帖子，该训练营提供全栈网络开发计划奖学金。",-1)),r[46]||(r[46]=l("p",null,"申请流程很简单，所以我就申请了。我很快收到了一份自发的面试邀请。当时的我感到沮丧、凌乱又绝望，没有任何准备就参加了面试，所以我全程非常诚实。整个面试的谈话同样坦诚，对此我深表感激。",-1)),l("p",null,[r[17]||(r[17]=i("面试官是 ",-1)),e(o,{href:"https://www.coyotiv.com/"},{default:t(()=>[...r[16]||(r[16]=[i("Coyotiv 软件工程学院",-1)])]),_:1}),r[18]||(r[18]=i(" 的创始人 Armagan Amcalar。具有音乐背景的Armagan 富有创造力，对周围的世界有着批判性的思考。这所学校是在他为柏林的 Women Techmakers 提供免费速成课程三年后创办的。他没有死记硬背多样性演讲，而是根据它采取行动，为所有全职参与者提供奖学金。",-1))]),r[47]||(r[47]=l("p",null,"我获得了奖学金，并与其他四个人（其中 3 名女性）一起组成了第一批学生。训练营持续了高强度的 17 周。它对改变我对代码的看法极为重要。与我尝试学习的其他地方不同，Armagan 并不关心我们选择什么编程框架。相反，这一切都是为了理解我们在做什么，并将软件工程视为一种创造性的、强大的工具来塑造我们生活的世界。我得到的不仅仅是奖学金，我还收获了一个朋友和终身导师，他为我提供华丽转身的机会，打开了一扇通往美好生活的大门。",-1)),r[48]||(r[48]=l("p",null,"你是不是觉得我的反应太夸张了？你可以问问我身边的人。我的搭档此时已经认识我大约 14 年了，他是这样评价我的变化的：我变得纪律严明，充满活力，一路走来我对学到的东西感到高兴，就软件及其相关的事物进行深入对话，不再困惑矛盾，我放弃了终生的艺术事业，转而找到了人生的目标。由于我的变化实在惊人，他参加了我后面的几届训练营项目。",-1)),r[49]||(r[49]=l("p",null,"学校为我提供了技术知识、面试培训、简历支持和公开演讲培训。毕业不仅仅要求开发个人的全栈项目，还必须通过在 npm 上发布一个库来回馈开源，因为有如此多的软件是基于开源构建的。Node 包管理器（npm）是一个 JavaScript 包存储库，允许你通过在基于 Javascript 的项目中轻松安装代码来重用代码。尽管我参与自由软件运动和开源已经十多年了，但我从没想过我可以用实际代码回馈它。",-1)),r[50]||(r[50]=l("h3",{id:"我的贡献",tabindex:"-1"},[i("我的贡献 "),l("a",{class:"header-anchor",href:"#我的贡献","aria-label":"Permalink to “我的贡献”"},"​")],-1)),l("p",null,[e(o,{href:"https://www.npmjs.com/package/rainbow-penguin"},{default:t(()=>[...r[19]||(r[19]=[i("彩虹企鹅",-1)])]),_:1}),r[20]||(r[20]=i(" 就这样诞生了。它是一个 npm 库，可以在开发人员敲代码时发送激励信息。 也许它不是一个非常实用的工具。但对我来说它依然是个必要的工具，这基于我个人的经历——我经历过学习编码的挫折，为 if-me 项目做出贡献，而且从其他学习者那里听到了许多类似的故事。",-1))]),r[51]||(r[51]=l("p",null,"通过我在这些编程社区的经历，我了解到编程远不止一行行的代码，拥有盟友是多么强大和有必要。无论你是谁或你自认为了解什么，自由和开源软件社区中都有机会。你的参与不一定要是大动作，因为盟友们的小小贡献加起来远大于一个人贡献的总和。迈出第一步。在开源领域中找到你的盟友。",-1)),r[52]||(r[52]=l("p",null,[l("em",null,"（题图：MJ:tech woman illustration in high resolution, very detailed, 8k）")],-1)),r[53]||(r[53]=l("hr",null,null,-1)),l("p",null,[r[22]||(r[22]=i("via: ",-1)),e(o,{href:"https://opensource.com/article/23/3/power-sisterhood-allyship-open-source"},{default:t(()=>[...r[21]||(r[21]=[i("https://opensource.com/article/23/3/power-sisterhood-allyship-open-source",-1)])]),_:1})]),l("p",null,[r[27]||(r[27]=i("作者：",-1)),e(o,{href:"https://opensource.com/users/discombobulateme"},{default:t(()=>[...r[23]||(r[23]=[i("Paloma Oliveira",-1)])]),_:1}),r[28]||(r[28]=i(" 选题：",-1)),e(o,{href:"https://github.com/lkxed/"},{default:t(()=>[...r[24]||(r[24]=[i("lkxed",-1)])]),_:1}),r[29]||(r[29]=i(" 译者：",-1)),e(o,{href:"https://github.com/XiaotingHuang22"},{default:t(()=>[...r[25]||(r[25]=[i("XiaotingHuang22",-1)])]),_:1}),r[30]||(r[30]=i(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:t(()=>[...r[26]||(r[26]=[i("wxy",-1)])]),_:1})]),l("p",null,[r[33]||(r[33]=i("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...r[31]||(r[31]=[i("LCTT",-1)])]),_:1}),r[34]||(r[34]=i(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:t(()=>[...r[32]||(r[32]=[i("Linux中国",-1)])]),_:1}),r[35]||(r[35]=i(" 荣誉推出",-1))])])}const L=n(u,[["render",d]]);export{P as __pageData,L as default};
